//! #495: discovery answers pass the same shared rows as the reference client.
#![cfg(feature = "wallet")]
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)] // #134: tests

use async_trait::async_trait;
use bsv_rs::wallet::wire::{WalletWire, WalletWireTransceiver};
use bsv_rs::Error;
use serde::Deserialize;
use serde_json::{value::RawValue, Value};

#[derive(Deserialize)]
struct Recording {
    source: String,
    node: String,
    rows: Vec<Case>,
}

#[derive(Deserialize)]
struct Case {
    name: String,
    row: u32,
    call: String,
    // Keep the reference's attribute insertion order all the way into IndexMap.
    args: Box<RawValue>,
    request_hex: String,
    frame_sha256: String,
    response_hex: Option<String>,
    response_parts: Option<Vec<Part>>,
    reference: Value,
    value: Option<Value>,
}

#[derive(Deserialize)]
struct Part {
    hex: String,
    repeat: usize,
}

struct RecordedWire {
    response: Vec<u8>,
    request: Vec<u8>,
}

#[async_trait]
impl WalletWire for RecordedWire {
    async fn transmit_to_wallet(&self, request: &[u8]) -> Result<Vec<u8>, Error> {
        assert_eq!(
            request, self.request,
            "the request bytes must stay unchanged"
        );
        Ok(self.response.clone())
    }
}

async fn invoke(case: &Case) -> Result<Value, Error> {
    let response = match &case.response_hex {
        Some(hex) => hex::decode(hex).unwrap(),
        None => case
            .response_parts
            .as_ref()
            .unwrap()
            .iter()
            .flat_map(|part| hex::decode(&part.hex).unwrap().repeat(part.repeat))
            .collect(),
    };
    assert_eq!(
        hex::encode(bsv_rs::primitives::sha256(&response)),
        case.frame_sha256,
        "{}: the recorded frame must stay byte-identical",
        case.name
    );
    let wallet = WalletWireTransceiver::new(RecordedWire {
        response,
        request: hex::decode(&case.request_hex).unwrap(),
    });
    let result = match case.call.as_str() {
        "discoverByIdentityKey" => {
            wallet
                .discover_by_identity_key(
                    serde_json::from_str(case.args.get()).unwrap(),
                    Some("fixtures.invalid"),
                )
                .await
        }
        "discoverByAttributes" => {
            wallet
                .discover_by_attributes(
                    serde_json::from_str(case.args.get()).unwrap(),
                    Some("fixtures.invalid"),
                )
                .await
        }
        other => panic!("unrecorded discovery call {other}"),
    }?;
    Ok(serde_json::to_value(result).unwrap())
}

async fn check(row: u32, accepting_call: Option<&str>) {
    let recording: Recording = serde_json::from_str(RECORDING).unwrap();
    assert_eq!(recording.source, "ts-stack@edf6e03");
    assert_eq!(recording.node, "v22.18.0");
    let cases: Vec<_> = recording
        .rows
        .iter()
        .filter(|case| {
            if let Some(call) = accepting_call {
                case.call == call && case.reference["accepted"] == true
            } else {
                case.row == row
            }
        })
        .collect();
    assert!(!cases.is_empty(), "no recorded discovery frames for {row}");
    let mut mismatches = Vec::new();
    for case in &cases {
        let actual = invoke(case).await;
        let matches = match &actual {
            Ok(value) => case.reference["accepted"] == true && case.value.as_ref() == Some(value),
            Err(Error::WalletError(words)) => {
                case.reference["code"].is_null()
                    && case.reference["message"].as_str() == Some(words)
            }
            _ => false,
        };
        if !matches {
            // A graph witness has 10,000 certificates: keep the RED log bounded.
            let verdict = match actual {
                Ok(_) => "Ok(discovery answer)".to_string(),
                Err(error) => format!("{error:?}"),
            };
            mismatches.push(format!(
                "{}: {verdict}; recorded {}",
                case.name, case.reference
            ));
        }
    }
    assert!(
        mismatches.is_empty(),
        "row {row}: {} frames\n{}",
        cases.len(),
        mismatches.join("\n")
    );
}

macro_rules! row {
    ($name:ident, $number:literal) => {
        #[tokio::test]
        async fn $name() {
            check($number, None).await;
        }
    };
}

row!(row_03_discovery_snapshot_graph_495, 3);
row!(row_74_discovery_signed_certificate_495, 74);
row!(row_76_discovery_identity_binding_495, 76);
row!(row_79_discovery_certifier_metadata_495, 79);
row!(row_80_discovery_public_keyring_495, 80);
row!(row_81_discovery_any_attributes_495, 81);
row!(row_82_discovery_named_attributes_495, 82);

#[tokio::test]
async fn accepting_identity_frames_495() {
    check(0, Some("discoverByIdentityKey")).await;
}

#[tokio::test]
async fn accepting_attribute_frames_495() {
    check(0, Some("discoverByAttributes")).await;
}

